package android.media.session; public class MediaController {final String pkg; public MediaController(String p){pkg=p;} public String getPackageName(){return pkg;} public android.media.MediaMetadata getMetadata(){if(pkg.equals("unselected"))throw new AssertionError("SECRET MUST NOT BE READ");if(System.getProperty("scenario").equals("null-content"))return null;return new android.media.MediaMetadata();}public PlaybackState getPlaybackState(){if(pkg.equals("unselected"))throw new AssertionError("SECRET MUST NOT BE READ");if(System.getProperty("scenario").equals("null-content"))return null;return new PlaybackState();}}
